const g = $input.first().json;
const e = g.estado_actual || {};
const u = g.umbrales || { co2:{limite:400}, sonido:{limite:80}, distancia:{limite:20} };

// Sin evaluacion en codigo: el LLM recibe el estado completo y decide si actuar.
let prompt = "Eres un agente autonomo de control de un hogar inteligente. TU decides si la situacion requiere actuar; el sistema no pre-evalua nada.\n\n";
prompt += "Estado actual de los sensores:\n";
prompt += "- CO2: " + e.co2 + " ppm\n";
prompt += "- Sonido: " + e.sonido + " dB\n";
prompt += "- Distancia: " + e.distancia + " cm\n";
prompt += "- Persona detectada por camara: " + (e.persona ? "si" : "no") + "\n";
prompt += "- LED de alarma: " + (e.led ? "encendido" : "apagado") + "\n\n";
prompt += "Umbrales de referencia configurados por el usuario:\n";
prompt += "- CO2: peligroso por encima de " + u.co2.limite + " ppm\n";
prompt += "- Sonido: peligroso por encima de " + u.sonido.limite + " dB\n";
prompt += "- Distancia: peligroso por debajo de " + u.distancia.limite + " cm\n\n";
prompt += "Herramientas disponibles:\n- activar_actuador(dispositivo, estado)  // dispositivo: led, estado: true|false\n- enviar_notificacion(mensaje)\n- registrar_evento(descripcion)\n\n";
prompt += "Analiza el estado comparandolo con los umbrales de referencia y decide que acciones ejecutar:\n";
prompt += "- Si hay alguna condicion peligrosa: como minimo activa el LED y envia una notificacion describiendola.\n";
prompt += "- Si todo esta normal: devuelve la lista de acciones vacia, o apaga el LED si estaba encendido sin motivo.\n";
prompt += "- Basate SOLO en los datos entregados; no inventes valores.\n\n";
prompt += "Responde SOLO en JSON: {\"acciones\":[{\"herramienta\":\"activar_actuador\",\"parametros\":{\"dispositivo\":\"led\",\"estado\":true}}],\"razonamiento\":\"...\"}";

return [{ json: { model: 'llama3.2:3b', prompt: prompt, stream: false, format: 'json' } }];

const resp = $json.response || $json.data || '';
let decision;
try { decision = JSON.parse(resp); } catch(err) { decision = { acciones: [], razonamiento: 'error parse: ' + String(resp).slice(0,150) }; }
const acciones = decision.acciones || [];
const ejecutadas = [];
for (const acc of acciones) {
  const tool = acc.herramienta || acc.tool || acc.accion || acc.action;
  const p = acc.parametros || acc.params || acc;
  if (tool === 'activar_actuador') {
    try {
      await this.helpers.httpRequest({ method:'POST', url:'http://nodered:1880/agente/accion', body:{dispositivo:p.dispositivo, estado:p.estado}, json:true });
      ejecutadas.push('actuador ' + p.dispositivo + '=' + p.estado);
    } catch(err) { ejecutadas.push('error actuador: ' + err.message); }
  } else if (tool === 'enviar_notificacion') {
    ejecutadas.push('notif: ' + (p.mensaje||''));
  } else if (tool === 'registrar_evento') {
    ejecutadas.push('evento: ' + (p.descripcion||''));
  }
}
const raz = String(decision.razonamiento||'').replace(/"/g,"'").slice(0,200);
const accStr = (ejecutadas.join(' | ')||'ninguna').replace(/"/g,"'").slice(0,200);
const line = 'agente razonamiento="'+raz+'",acciones="'+accStr+'",num='+acciones.length;
try {
  await this.helpers.httpRequest({ method:'POST', url:'http://influxdb:8086/api/v2/write?org=smarthome&bucket=sensores&precision=s', headers:{'Authorization':'Token smarthome_token_2024','Content-Type':'text/plain'}, body: line });
} catch(err) {}
return [{ json: { razonamiento: decision.razonamiento, acciones_ejecutadas: ejecutadas, total: acciones.length } }];
